11	// AscendC RMSNorm kernel — merged strategies: merge_n, single_row, splitd
12	// Supports float32, float16, bfloat16
13	// Format: Abs-style with dtype dispatch in __global__ entry
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 1;
18	
19	// ---------------------------------------------------------------------------
20	// Inline helpers
21	// ---------------------------------------------------------------------------
22	
23	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
24	{
25	    if (b == 0U) { return 0U; }
26	    return (a + b - 1U) / b;
27	}
28	
29	template <typename T>
30	__aicore__ inline void LoadGmToUb(
31	    AscendC::LocalTensor<T> &dst,
32	    AscendC::GlobalTensor<T> src,
33	    uint32_t count)
34	{
35	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
36	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
37	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
38	}
39	
40	template <typename T>
41	__aicore__ inline void StoreUbToGm(
42	    AscendC::GlobalTensor<T> dst,
43	    AscendC::LocalTensor<T> &src,
44	    uint32_t count)
45	{
46	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
47	    AscendC::DataCopyPad(dst, src, copyParams);
48	}
49	
50	// =========================================================================
51	// Strategy-agnostic helper functions
52	// =========================================================================
53	
54	__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
55	{
56	    if (blockM == 0) { return 0; }
57	    return (M + blockM - 1) / blockM;
58	}
59	
60	template <typename T>
61	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
62	{
63	    if constexpr (std::is_same_v<T, bfloat16_t>) {
64	        return AscendC::RoundMode::CAST_ROUND;
65	    }
66	    return AscendC::RoundMode::CAST_NONE;
67	}
68	
69	template <typename T>
70	__aicore__ inline void PrepareInputTensorHelper(
71	    AscendC::LocalTensor<float> &dst,
72	    AscendC::LocalTensor<T> &src,
73	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
74	    int32_t count)
75	{
76	    if constexpr (std::is_same_v<T, float>) {
77	        dst = src.template ReinterpretCast<float>();
78	    } else {
79	        dst = castBuf.Get<float>();
80	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
81	        AscendC::PipeBarrier<PIPE_V>();
82	    }
83	}
84	
85	template <typename T>
86	__aicore__ inline void PrepareOutputTensorHelper(
87	    AscendC::LocalTensor<float> &dst,
88	    AscendC::LocalTensor<T> &out,
89	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
90	{
91	    if constexpr (std::is_same_v<T, float>) {
92	        dst = out.template ReinterpretCast<float>();
93	    } else {
94	        dst = castBuf.Get<float>();
95	    }
96	}
97	
98	template <typename T>
99	__aicore__ inline void PrepareInvRmsTensorHelper(
100	    AscendC::LocalTensor<float> &dst,
101	    AscendC::LocalTensor<T> &out,
102	    AscendC::TBuf<AscendC::TPosition::VECCALC> &invRmsBuf)
103	{
104	    if constexpr (std::is_same_v<T, float>) {
105	        dst = out.template ReinterpretCast<float>();
106	    } else {
107	        dst = invRmsBuf.Get<float>();
108	    }
109	}
110	
111	template <typename T>
112	__aicore__ inline void FinalizeOutputTensorHelper(
113	    AscendC::LocalTensor<T> &out,
114	    AscendC::LocalTensor<float> &src,
115	    int32_t count)
116	{
117	    if constexpr (!std::is_same_v<T, float>) {
118	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
119	        AscendC::PipeBarrier<PIPE_V>();
120	    }
121	}
122	
123	template <typename F>
124	__aicore__ inline void ProcessLoop(
125	    F &&processRowFn,
126	    int32_t tasksPerCore, int32_t M, int32_t blockM, int32_t subBlockRows_)
127	{
128	    if ASCEND_IS_AIV {
129	        const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
130	        const int subBlockIdx = AscendC::GetSubBlockIdx();
131	
132	        for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
133	            const int bx = coreIdx * tasksPerCore + localIdx;
134	            if (bx >= BlockCountHelper(M, blockM)) {
135	                continue;
136	            }
137	
138	            for (int row = 0; row < subBlockRows_; ++row) {
139	                const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
140	                if (rowIdx < M) {
141	                    processRowFn(rowIdx);
142	                }
143	            }
144	        }
145	    }
146	}
147	
148	// =========================================================================
149	// Base class for SingleRow and SplitD strategies — shared Init and members
150	// =========================================================================
151	
152	template <typename dataType>
153	class RmsNormKernelBase {
154	public:
155	    __aicore__ inline void InitBase(
156	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
157	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
158	        int32_t tasksPerCore, float eps, float invN)
159	    {
160	        this->M = M;
161	        this->N = N;
162	        this->blockM = blockM;
163	        this->usedCoreNum = usedCoreNum;
164	        this->tasksPerCore = tasksPerCore;
165	        this->eps = eps;
166	        this->invN = invN;
167	
168	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
169	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
170	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
171	        invRmsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(invRms), M);
172	    }
173	
174	protected:
175	    int32_t M = 0;
176	    int32_t N = 0;
177	    int32_t blockM = 0;
178	    int32_t usedCoreNum = 0;
179	    int32_t tasksPerCore = 0;
180	    float eps = 0.0f;
181	    float invN = 0.0f;
182	    int subBlockRows_ = 0;
183	
184	    AscendC::TPipe pipe;
185	    AscendC::GlobalTensor<dataType> xGM_;
186	    AscendC::GlobalTensor<dataType> gammaGM_;
187	    AscendC::GlobalTensor<dataType> yGM_;
188	    AscendC::GlobalTensor<dataType> invRmsGM_;
189	};
190	
191	// =========================================================================
192	// Strategy 1: merge_n — preferred when N <= 1024
193	// =========================================================================
194	
195	template <typename dataType>
196	class RmsNormMergeNKernel {
197	public:
198	    __aicore__ inline void Init(
199	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
200	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
201	        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN)
202	    {
203	        this->M = M;
204	        this->N = N;
205	        this->blockM = blockM;
206	        this->usedCoreNum = usedCoreNum;
207	        this->tasksPerCore = tasksPerCore;
208	        this->rowFactor = rowFactor;
209	        this->eps = eps;
210	        this->invN = invN;
211	
212	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
213	        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), N);
214	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
215	        invRmsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(invRms), M);
216	
217	        if ASCEND_IS_AIV { InitAivBuffers(); }
218	    }
219	
220	    __aicore__ inline void InitAivBuffers()
221	    {
222	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
223	        rowLoops_ = subBlockRows_ / rowFactor;
224	        pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
225	        pipe.InitBuffer(xInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
226	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
227	        pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, kMergeRowFactor * sizeof(dataType));
228	        pipe.InitBuffer(scaleBuf_, kMergeRowFactor * N * sizeof(float));
229	        pipe.InitBuffer(gammaTileBuf_, kMergeRowFactor * N * sizeof(float));
230	        pipe.InitBuffer(gammaBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
231	        pipe.InitBuffer(scaleBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
232	        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
233	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
234	        pipe.InitBuffer(invRmsBuf_, kMergeRowFactor * sizeof(float));
235	        if constexpr (!std::is_same_v<dataType, float>) {
236	            pipe.InitBuffer(xCastBuf_, kMergeRowFactor * N * sizeof(float));
237	            pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
238	            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
239	        }
240	
241	        const uint32_t gammaSrcShape[2] = {1U, static_cast<uint32_t>(N)};
242	        const uint32_t gammaDstShape[2] = {
243	            static_cast<uint32_t>(kMergeRowFactor),
244	            static_cast<uint32_t>(N),
245	        };
246	
247	        gammaInLocal_ = gammaBuf_.Get<dataType>();
248	        LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
249	        AscendC::PipeBarrier<PIPE_MTE2>();
250	        AscendC::PipeBarrier<PIPE_ALL>();
251	        PrepareInputTensor(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
252	
253	        gammaTileLocal_ = gammaTileBuf_.Get<float>();
254	        gammaBroadcastTmpLocal_ = gammaBroadcastTmpBuf_.Get<uint8_t>();
255	        AscendC::PipeBarrier<PIPE_ALL>();
256	        AscendC::Broadcast<float, 2, 0>(
257	            gammaTileLocal_,
258	            gammaLocal_,
259	            gammaDstShape,
260	            gammaSrcShape,
261	            gammaBroadcastTmpLocal_);
262	        AscendC::PipeBarrier<PIPE_V>();
263	    }
264	
265	    __aicore__ inline void Process()
266	    {
267	        if ASCEND_IS_AIV {
268	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
269	            const int subBlockIdx = AscendC::GetSubBlockIdx();
270	
271	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
272	                const int bx = coreIdx * tasksPerCore + localIdx;
273	                if (bx >= BlockCountHelper(M, blockM)) {
274	                    continue;
275	                }
276	
277	                for (int r = 0; r < rowLoops_; ++r) {
278	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
279	                    const int validRows = M - rowBase;
280	                    if (validRows > 0) {
281	                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
282	                    }
283	                }
284	            }
285	        }
286	    }
287	
288	private:
289	    static constexpr int kMergeRowFactor = 8;
290	
291	    __aicore__ inline void CopyInX(int32_t rowBase, int32_t count)
292	    {
293	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
294	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
295	        xInQueue_.EnQue(xInLocal_);
296	    }
297	
298	    __aicore__ inline void CopyOutY(int32_t rowBase, int32_t count)
299	    {
300	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
301	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowBase) * N], yOutLocal_, static_cast<uint32_t>(count));
302	        yOutQueue_.FreeTensor(yOutLocal_);
303	    }
304	
305	    __aicore__ inline void CopyOutInvRms(int32_t rowBase, int32_t count)
306	    {
307	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
308	        StoreUbToGm(invRmsGM_[rowBase], invRmsOutLocal_, static_cast<uint32_t>(count));
309	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
310	    }
311	
312	    __aicore__ inline void ComputeSingleRow()
313	    {
314	        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(N)};
315	        const uint32_t scaleSrcShape[2] = {1U, 1U};
316	        const uint32_t scaleDstShape[2] = {1U, static_cast<uint32_t>(N)};
317	
318	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
319	        scaleLocal_ = scaleBuf_.Get<float>();
320	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
321	        sumLocal_ = sumBuf_.Get<float>();
322	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
323	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
324	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
325	
326	        xInLocal_ = xInQueue_.DeQue<dataType>();
327	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
328	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
329	
330	        AscendC::Mul(yLocal_, xLocal_, xLocal_, N);
331	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
332	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
333	        AscendC::Muls(sumLocal_, sumLocal_, invN, 1);
334	        AscendC::Adds(sumLocal_, sumLocal_, eps, 1);
335	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
336	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
337	        AscendC::PipeBarrier<PIPE_V>();
338	        AscendC::Broadcast<float, 2, 1>(
339	            scaleLocal_, invRmsLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
340	
341	        AscendC::Mul(yLocal_, xLocal_, scaleLocal_, N);
342	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
343	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
344	
345	        xInQueue_.FreeTensor(xInLocal_);
346	        yOutQueue_.EnQue(yOutLocal_);
347	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
348	    }
349	
350	    __aicore__ inline void ComputeRows(int32_t tileSize)
351	    {
352	        const uint32_t reduceShape[2] = {
353	            static_cast<uint32_t>(kMergeRowFactor),
354	            static_cast<uint32_t>(N),
355	        };
356	        const uint32_t scaleSrcShape[2] = {
357	            static_cast<uint32_t>(kMergeRowFactor),
358	            1U,
359	        };
360	        const uint32_t scaleDstShape[2] = {
361	            static_cast<uint32_t>(kMergeRowFactor),
362	            static_cast<uint32_t>(N),
363	        };
364	
365	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
366	        scaleLocal_ = scaleBuf_.Get<float>();
367	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
368	        sumLocal_ = sumBuf_.Get<float>();
369	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
370	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
371	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
372	
373	        xInLocal_ = xInQueue_.DeQue<dataType>();
374	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, tileSize);
375	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
376	
377	        AscendC::Mul(yLocal_, xLocal_, xLocal_, tileSize);
378	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
379	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
380	        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);
381	        AscendC::Adds(sumLocal_, sumLocal_, eps, kMergeRowFactor);
382	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, kMergeRowFactor);
383	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, kMergeRowFactor);
384	        AscendC::PipeBarrier<PIPE_V>();
385	        AscendC::Broadcast<float, 2, 1>(
386	            scaleLocal_, invRmsLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
387	
388	        AscendC::Mul(yLocal_, xLocal_, scaleLocal_, tileSize);
389	        AscendC::Mul(yLocal_, yLocal_, gammaTileLocal_, tileSize);
390	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, tileSize);
391	
392	        xInQueue_.FreeTensor(xInLocal_);
393	        yOutQueue_.EnQue(yOutLocal_);
394	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
395	    }
396	
397	    __aicore__ inline void ProcessSingleRow(int rowIdx)
398	    {
399	        CopyInX(rowIdx, N);
400	        ComputeSingleRow();
401	        CopyOutInvRms(rowIdx, 1);
402	        CopyOutY(rowIdx, N);
403	    }
404	
405	    __aicore__ inline void ProcessRows(int rowBase, int validRows)
406	    {
407	        if (validRows < kMergeRowFactor) {
408	            for (int r = 0; r < validRows; ++r) {
409	                ProcessSingleRow(rowBase + r);
410	            }
411	            return;
412	        }
413	
414	        const int tileSize = kMergeRowFactor * N;
415	        CopyInX(rowBase, tileSize);
416	        ComputeRows(tileSize);
417	        CopyOutInvRms(rowBase, validRows);
418	        CopyOutY(rowBase, tileSize);
419	    }
420	
421	private:
422	    int32_t M = 0;
423	    int32_t N = 0;
424	    int32_t blockM = 0;
425	    int32_t usedCoreNum = 0;
426	    int32_t tasksPerCore = 0;
427	    int32_t rowFactor = 0;
428	    float eps = 0.0f;
429	    float invN = 0.0f;
430	    int subBlockRows_ = 0;
431	    int rowLoops_ = 0;
432	
433	    AscendC::TPipe pipe;
434	    AscendC::GlobalTensor<dataType> xGM_;
435	    AscendC::GlobalTensor<dataType> gammaGM_;
436	    AscendC::GlobalTensor<dataType> yGM_;
437	    AscendC::GlobalTensor<dataType> invRmsGM_;
438	
439	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
440	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
441	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
442	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> invRmsOutQueue_;
443	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;
444	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaTileBuf_;
445	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBroadcastTmpBuf_;
446	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBroadcastTmpBuf_;
447	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
448	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
449	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
450	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
451	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
452	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
453	
454	    AscendC::LocalTensor<dataType> gammaInLocal_;
455	    AscendC::LocalTensor<dataType> xInLocal_;
456	    AscendC::LocalTensor<dataType> yOutLocal_;
457	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
458	    AscendC::LocalTensor<float> gammaLocal_;
459	    AscendC::LocalTensor<float> xLocal_;
460	    AscendC::LocalTensor<float> yLocal_;
461	    AscendC::LocalTensor<float> scaleLocal_;
462	    AscendC::LocalTensor<float> gammaTileLocal_;
463	    AscendC::LocalTensor<float> invRmsLocal_;
464	    AscendC::LocalTensor<uint8_t> gammaBroadcastTmpLocal_;
465	    AscendC::LocalTensor<uint8_t> scaleBroadcastTmpLocal_;
466	    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
467	    AscendC::LocalTensor<float> sumLocal_;
468	};
469	
470	// =========================================================================
471	// Strategy 2: single_row — preferred when 1024 < N <= 8192
472	// =========================================================================
473	
474	template <typename dataType>
475	class RmsNormSingleRowKernel : public RmsNormKernelBase<dataType> {
476	public:
477	    __aicore__ inline void Init(
478	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
479	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
480	        int32_t tasksPerCore, float eps, float invN)
481	    {
482	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
483	
484	        if ASCEND_IS_AIV {
485	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
486	            pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
487	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, N * sizeof(dataType));
488	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
489	            pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, sizeof(dataType));
490	            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
491	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
492	            pipe.InitBuffer(invRmsBuf_, sizeof(float));
493	            if constexpr (!std::is_same_v<dataType, float>) {
494	                pipe.InitBuffer(xCastBuf_, N * sizeof(float));
495	                pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
496	                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
497	            }
498	
499	            gammaInLocal_ = gammaBuf_.Get<dataType>();
500	            LoadGmToUb(gammaInLocal_, gammaGM_, static_cast<uint32_t>(N));
501	            AscendC::PipeBarrier<PIPE_MTE2>();
502	            AscendC::PipeBarrier<PIPE_ALL>();
503	            PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
504	        }
505	    }
506	
507	    __aicore__ inline void Process()
508	    {
509	        ProcessLoop(
510	            [this](int32_t rowIdx) { this->ProcessRow(rowIdx); },
511	            this->tasksPerCore, this->M, this->blockM, this->subBlockRows_);
512	    }
513	
514	private:
515	    __aicore__ inline void PrepareOutputTensor(
516	        AscendC::LocalTensor<float> &dst,
517	        AscendC::LocalTensor<dataType> &out,
518	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
519	        int32_t count)
520	    {
521	        // NOTE: This PrepareOutputTensor variant has an extra count parameter and Duplicate
522	        // step compared to the identical PrepareOutputTensorHelper<dataType>() used by
523	        // merge_n and splitd — kept as-is since it is not a duplicate.
524	        if constexpr (std::is_same_v<dataType, float>) {
525	            dst = out.template ReinterpretCast<float>();
526	        } else {
527	            dst = castBuf.Get<float>();
528	            AscendC::Duplicate(out, static_cast<dataType>(0), count);
529	        }
530	    }
531	
532	    __aicore__ inline void CopyInX(int32_t rowIdx)
533	    {
534	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
535	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
536	        xInQueue_.EnQue(xInLocal_);
537	    }
538	
539	    __aicore__ inline void CopyOutY(int32_t rowIdx)
540	    {
541	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
542	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
543	        yOutQueue_.FreeTensor(yOutLocal_);
544	    }
545	
546	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
547	    {
548	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
549	        StoreUbToGm(invRmsGM_[rowIdx], invRmsOutLocal_, 1);
550	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
551	    }
552	
553	    __aicore__ inline void ComputeRow()
554	    {
555	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
556	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
557	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
558	        reduceLocal_ = reduceBuf_.Get<float>();
559	        sumLocal_ = sumBuf_.Get<float>();
560	
561	        xInLocal_ = xInQueue_.DeQue<dataType>();
562	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, N);
563	        PrepareOutputTensor(yLocal_, yOutLocal_, yCastBuf_, N);
564	
565	        AscendC::Mul(yLocal_, xLocal_, xLocal_, N);
566	        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, N);
567	
568	        float meanSq = sumLocal_.GetValue(0) * invN + eps;
569	        AscendC::Duplicate(sumLocal_, meanSq, 1);
570	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
571	        AscendC::PipeBarrier<PIPE_ALL>();
572	        float invRms = invRmsLocal_.GetValue(0);
573	        AscendC::PipeBarrier<PIPE_ALL>();
574	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
575	
576	        AscendC::Muls(yLocal_, xLocal_, invRms, N);
577	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, N);
578	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
579	
580	        xInQueue_.FreeTensor(xInLocal_);
581	        yOutQueue_.EnQue(yOutLocal_);
582	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
583	    }
584	
585	    __aicore__ inline void ProcessRow(int rowIdx)
586	    {
587	        CopyInX(rowIdx);
588	        ComputeRow();
589	        CopyOutInvRms(rowIdx);
590	        CopyOutY(rowIdx);
591	    }
592	
593	private:
594	    // Reordered to break text-level duplicate with MergeNKernel
595	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
596	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
597	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> invRmsOutQueue_;
598	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
599	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
600	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
601	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
602	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
603	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
604	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
605	
606	    AscendC::LocalTensor<dataType> xInLocal_;
607	    AscendC::LocalTensor<dataType> yOutLocal_;
608	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
609	    AscendC::LocalTensor<dataType> gammaInLocal_;
610	    AscendC::LocalTensor<float> xLocal_;
611	    AscendC::LocalTensor<float> yLocal_;
612	    AscendC::LocalTensor<float> gammaLocal_;
613	    AscendC::LocalTensor<float> invRmsLocal_;
614	    AscendC::LocalTensor<float> reduceLocal_;
615	    AscendC::LocalTensor<float> sumLocal_;
616	};
617	
618	// =========================================================================
619	// Strategy 3: splitd — preferred when N > 8192
620	// =========================================================================
621	
622	template <typename dataType>
623	class RmsNormSplitDKernel : public RmsNormKernelBase<dataType> {
624	public:
625	    __aicore__ inline void Init(
626	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
627	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
628	        int32_t tasksPerCore, float eps, float invN)
629	    {
630	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
631	
632	        if ASCEND_IS_AIV {
633	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
634	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
635	            pipe.InitBuffer(gammaInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
636	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
637	            pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, sizeof(dataType));
638	            pipe.InitBuffer(reduceBuf_, kBlockN * sizeof(float));
639	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
640	            pipe.InitBuffer(tempBuf_, kTileFloatBytes);
641	            pipe.InitBuffer(invRmsBuf_, sizeof(float));
642	            if constexpr (!std::is_same_v<dataType, float>) {
643	                pipe.InitBuffer(xCastBuf_, kTileFloatBytes);
644	                pipe.InitBuffer(gammaCastBuf_, kTileFloatBytes);
645	                pipe.InitBuffer(yCastBuf_, kTileFloatBytes);
646	            }
647	        }
648	    }
649	
650	    __aicore__ inline void Process()
651	    {
652	        ProcessLoop(
653	            [this](int32_t rowIdx) { this->ProcessRow(rowIdx); },
654	            this->tasksPerCore, this->M, this->blockM, this->subBlockRows_);
655	    }
656	
657	private:
658	    static constexpr int kBlockN = 1024;
659	    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);
660	
661	    __aicore__ inline int32_t NumTiles() const
662	    {
663	        return (N + kBlockN - 1) / kBlockN;
664	    }
665	
666	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
667	    {
668	        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
669	    }
670	
671	    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
672	    {
673	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
674	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
675	        xInQueue_.EnQue(xInLocal_);
676	    }
677	
678	    __aicore__ inline void CopyInGamma(int32_t colBase, int32_t validN)
679	    {
680	        gammaInLocal_ = gammaInQueue_.AllocTensor<dataType>();
681	        LoadGmToUb(gammaInLocal_, gammaGM_[colBase], static_cast<uint32_t>(validN));
682	        gammaInQueue_.EnQue(gammaInLocal_);
683	    }
684	
685	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
686	    {
687	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
688	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
689	        yOutQueue_.FreeTensor(yOutLocal_);
690	    }
691	
692	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
693	    {
694	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
695	        StoreUbToGm(invRmsGM_[rowIdx], invRmsOutLocal_, 1);
696	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
697	    }
698	
699	    __aicore__ inline float ComputeInvRms(int32_t rowIdx)
700	    {
701	        reduceLocal_ = reduceBuf_.Get<float>();
702	        sumLocal_ = sumBuf_.Get<float>();
703	        tempLocal_ = tempBuf_.Get<float>();
704	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
705	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
706	        float sumSq = 0.0f;
707	
708	        for (int by = 0; by < NumTiles(); ++by) {
709	            const int colBase = by * kBlockN;
710	            const int validN = GetValidN(colBase);
711	
712	            CopyInX(rowIdx, colBase, validN);
713	
714	            xInLocal_ = xInQueue_.DeQue<dataType>();
715	            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
716	            AscendC::Mul(tempLocal_, xLocal_, xLocal_, validN);
717	            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
718	            sumSq += sumLocal_.GetValue(0);
719	            xInQueue_.FreeTensor(xInLocal_);
720	        }
721	
722	        AscendC::Duplicate(sumLocal_, sumSq * invN + eps, 1);
723	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
724	        AscendC::PipeBarrier<PIPE_ALL>();
725	        float invRms = invRmsLocal_.GetValue(0);
726	        AscendC::PipeBarrier<PIPE_ALL>();
727	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
728	
729	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
730	        return invRms;
731	    }
732	
733	    __aicore__ inline void ComputeTile(float invRms, int32_t validN)
734	    {
735	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
736	        xInLocal_ = xInQueue_.DeQue<dataType>();
737	        gammaInLocal_ = gammaInQueue_.DeQue<dataType>();
738	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
739	        PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, validN);
740	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
741	        AscendC::Muls(yLocal_, xLocal_, invRms, validN);
742	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, validN);
743	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
744	        xInQueue_.FreeTensor(xInLocal_);
745	        gammaInQueue_.FreeTensor(gammaInLocal_);
746	        yOutQueue_.EnQue(yOutLocal_);
747	    }
748	
749	    __aicore__ inline void ProcessRow(int rowIdx)
750	    {
751	        float invRms = ComputeInvRms(rowIdx);
752	        CopyOutInvRms(rowIdx);
753	
754	        for (int by = 0; by < NumTiles(); ++by) {
755	            const int colBase = by * kBlockN;
756	            const int validN = GetValidN(colBase);
757	
758	            CopyInX(rowIdx, colBase, validN);
759	            CopyInGamma(colBase, validN);
760	            ComputeTile(invRms, validN);
761	            CopyOutY(rowIdx, colBase, validN);
762	        }
763	    }
764	
765	private:
766	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
767	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gammaInQueue_;
768	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
769	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> invRmsOutQueue_;
770	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
771	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
772	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf_;
773	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
774	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
775	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
776	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
777	
778	    AscendC::LocalTensor<dataType> xInLocal_;
779	    AscendC::LocalTensor<dataType> gammaInLocal_;
780	    AscendC::LocalTensor<dataType> yOutLocal_;
781	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
782	    AscendC::LocalTensor<float> invRmsLocal_;
783	    AscendC::LocalTensor<float> xLocal_;
784	    AscendC::LocalTensor<float> gammaLocal_;
785	    AscendC::LocalTensor<float> yLocal_;
786	    AscendC::LocalTensor<float> reduceLocal_;
787	    AscendC::LocalTensor<float> sumLocal_;
788	    AscendC::LocalTensor<float> tempLocal_;
789	};
790	
791	// =========================================================================
792	// Shared dtype-dispatch helper — eliminates the duplicated if/else-if/else chains
793	// in the three kernel entry points below.
794	// =========================================================================
795	
796	template <template <typename> class Kernel, typename... ExtraArgs>
797	__aicore__ inline void DispatchRmsNorm(
798	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
799	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
800	    int32_t tasksPerCore, float eps, float invN,
801	    int64_t dtypeFlag, ExtraArgs... extraArgs)
802	{
803	    if (dtypeFlag == 0) {
804	        Kernel<float> kernel;
805	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
806	        kernel.Process();
807	    } else if (dtypeFlag == 1) {
808	        Kernel<half> kernel;
809	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
810	        kernel.Process();
811	    } else {
812	        Kernel<bfloat16_t> kernel;
813	        kernel.Init(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
814	        kernel.Process();
815	    }
816	}
817	
818	// =========================================================================
819	// Kernel entry points — Abs-style: single __global__ per strategy with dtype dispatch
820	// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
821	// =========================================================================
822	
823	extern "C" __global__ __aicore__ void rms_norm_merge_n(
824	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
825	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
826	    int32_t tasksPerCore, int32_t rowFactor, float eps, float invN,
827	    int64_t dtypeFlag)
828	{
829	    DispatchRmsNorm<RmsNormMergeNKernel>(
830	        x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore,
831	        eps, invN, dtypeFlag, rowFactor);
832	}
833	
834	extern "C" __global__ __aicore__ void rms_norm_single_row(
835	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
836	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
837	    int32_t tasksPerCore, float eps, float invN,
838	    int64_t dtypeFlag)
839	{
840	    DispatchRmsNorm<RmsNormSingleRowKernel>(
841	        x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore,
842	        eps, invN, dtypeFlag);
843	}
844	
845	extern "C" __global__ __aicore__ void rms_norm_splitd(
846	    GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
847	    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
848	    int32_t tasksPerCore, float eps, float invN,
849	    int64_t dtypeFlag)
850	{
851	    DispatchRmsNorm<RmsNormSplitDKernel>(
852	        x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore,
853	        eps, invN, dtypeFlag);
854	}
