// ForeachAddcdivScalar kernel: out[i] = x[i] + y[i] / z[i] * scalar
// Pure Vector kernel with FP32 upcast for fp16/bf16

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelForeachAddcdivScalar {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR out,
        int32_t totalLength, int32_t formerNum, int32_t formerLength,
        int32_t tailLength, int32_t tileLength, float scalarVal)
    {
        this->totalLength = totalLength;
        this->formerNum = formerNum;
        this->formerLength = formerLength;
        this->tailLength = tailLength;
        this->tileLength = tileLength;
        this->scalarVal = scalarVal;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), totalLength);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), totalLength);
        zGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(z), totalLength);
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(out), totalLength);

        if ASCEND_IS_AIV {
            // Queues for double-buffered data movement
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileLength * sizeof(T));
            pipe.InitBuffer(yInQueue_, BUFFER_NUM, tileLength * sizeof(T));
            pipe.InitBuffer(zInQueue_, BUFFER_NUM, tileLength * sizeof(T));
            pipe.InitBuffer(outQueue_, BUFFER_NUM, tileLength * sizeof(T));

            // FP32 computation buffers
            pipe.InitBuffer(xFp32Buf_, tileLength * sizeof(float));
            pipe.InitBuffer(yFp32Buf_, tileLength * sizeof(float));
            pipe.InitBuffer(zFp32Buf_, tileLength * sizeof(float));
            pipe.InitBuffer(tmpFp32Buf_, tileLength * sizeof(float));

            if constexpr (!std::is_same_v<T, float>) {
                pipe.InitBuffer(xCastBuf_, tileLength * sizeof(float));
                pipe.InitBuffer(yCastBuf_, tileLength * sizeof(float));
                pipe.InitBuffer(zCastBuf_, tileLength * sizeof(float));
                pipe.InitBuffer(outCastBuf_, tileLength * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t tileNum = formerNum + (tailLength > 0 ? 1 : 0);
            for (int32_t i = 0; i < tileNum; ++i) {
                int32_t curLen = (i < formerNum) ? formerLength : tailLength;

                if (i < tileNum - 1) {
                    // Prefetch next tile for double buffering
                    CopyIn(i + 1, 0); // prefetch will be handled by double-buffer auto scheduling
                }

                CopyIn(i, curLen);
                Compute(curLen);
                CopyOut(i, curLen);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t tileIdx, int32_t curLen)
    {
        uint32_t offset = static_cast<uint32_t>(tileIdx) * static_cast<uint32_t>(formerLength);
        uint32_t byteLen = static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(T));

        // X input
        xInLocal_ = xInQueue_.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParamsX{1, byteLen, 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParamsX{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xInLocal_, xGM_[offset], copyParamsX, padParamsX);
        xInQueue_.EnQue(xInLocal_);

        // Y input
        yInLocal_ = yInQueue_.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParamsY{1, byteLen, 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParamsY{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(yInLocal_, yGM_[offset], copyParamsY, padParamsY);
        yInQueue_.EnQue(yInLocal_);

        // Z input
        zInLocal_ = zInQueue_.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParamsZ{1, byteLen, 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParamsZ{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(zInLocal_, zGM_[offset], copyParamsZ, padParamsZ);
        zInQueue_.EnQue(zInLocal_);
    }

    __aicore__ inline void Compute(int32_t curLen)
    {
        // Dequeue inputs
        xInLocal_ = xInQueue_.DeQue<T>();
        yInLocal_ = yInQueue_.DeQue<T>();
        zInLocal_ = zInQueue_.DeQue<T>();

        // Allocate output
        outLocal_ = outQueue_.AllocTensor<T>();

        // Prepare FP32 tensors (cast or reinterpret)
        if constexpr (std::is_same_v<T, float>) {
            xFp32Local_ = xInLocal_.template ReinterpretCast<float>();
            yFp32Local_ = yInLocal_.template ReinterpretCast<float>();
            zFp32Local_ = zInLocal_.template ReinterpretCast<float>();
            outFp32Local_ = outLocal_.template ReinterpretCast<float>();
        } else {
            xFp32Local_ = xCastBuf_.Get<float>();
            yFp32Local_ = yCastBuf_.Get<float>();
            zFp32Local_ = zCastBuf_.Get<float>();
            outFp32Local_ = outCastBuf_.Get<float>();

            AscendC::Cast(xFp32Local_, xInLocal_, AscendC::RoundMode::CAST_NONE, curLen);
            AscendC::Cast(yFp32Local_, yInLocal_, AscendC::RoundMode::CAST_NONE, curLen);
            AscendC::Cast(zFp32Local_, zInLocal_, AscendC::RoundMode::CAST_NONE, curLen);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Get intermediate FP32 buffers
        tmpFp32Local_ = tmpFp32Buf_.Get<float>();

        // Compute: tmp = y / z
        AscendC::Div(tmpFp32Local_, yFp32Local_, zFp32Local_, curLen);

        // Compute: tmp = tmp * scalar
        float s = scalarVal;
        AscendC::Muls(tmpFp32Local_, tmpFp32Local_, s, curLen);

        // Compute: out = x + tmp
        AscendC::Add(outFp32Local_, xFp32Local_, tmpFp32Local_, curLen);

        // Cast back to output dtype
        if constexpr (!std::is_same_v<T, float>) {
            AscendC::Cast(outLocal_, outFp32Local_, AscendC::RoundMode::CAST_ROUND, curLen);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // Free input tensors
        xInQueue_.FreeTensor(xInLocal_);
        yInQueue_.FreeTensor(yInLocal_);
        zInQueue_.FreeTensor(zInLocal_);

        // Enqueue output
        outQueue_.EnQue(outLocal_);
    }

    __aicore__ inline void CopyOut(int32_t tileIdx, int32_t curLen)
    {
        uint32_t offset = static_cast<uint32_t>(tileIdx) * static_cast<uint32_t>(formerLength);
        uint32_t byteLen = static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(T));

        outLocal_ = outQueue_.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, byteLen, 0, 0, 0};
        AscendC::DataCopyPad(outGM_[offset], outLocal_, copyParams);
        outQueue_.FreeTensor(outLocal_);
    }

private:
    int32_t totalLength = 0;
    int32_t formerNum = 0;
    int32_t formerLength = 0;
    int32_t tailLength = 0;
    int32_t tileLength = 0;
    float scalarVal = 0.0f;

    AscendC::TPipe pipe;

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;
    AscendC::GlobalTensor<T> zGM_;
    AscendC::GlobalTensor<T> outGM_;

    // Double-buffered queues
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> yInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> zInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;

    // FP32 computation buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> xFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> zFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpFp32Buf_;

    // Cast buffers (only used for fp16/bf16)
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> zCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outCastBuf_;

    // Local tensors
    AscendC::LocalTensor<T> xInLocal_;
    AscendC::LocalTensor<T> yInLocal_;
    AscendC::LocalTensor<T> zInLocal_;
    AscendC::LocalTensor<T> outLocal_;
    AscendC::LocalTensor<float> xFp32Local_;
    AscendC::LocalTensor<float> yFp32Local_;
    AscendC::LocalTensor<float> zFp32Local_;
    AscendC::LocalTensor<float> tmpFp32Local_;
    AscendC::LocalTensor<float> outFp32Local_;
};

// =========================================================================
// Kernel entry points — dtype dispatch via extern "C"
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void foreach_addcdiv_scalar(
    GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR out,
    int32_t totalLength, int32_t formerNum, int32_t formerLength,
    int32_t tailLength, int32_t tileLength, float scalarVal,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        KernelForeachAddcdivScalar<float> kernel;
        kernel.Init(x, y, z, out, totalLength, formerNum, formerLength,
                    tailLength, tileLength, scalarVal);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        KernelForeachAddcdivScalar<half> kernel;
        kernel.Init(x, y, z, out, totalLength, formerNum, formerLength,
                    tailLength, tileLength, scalarVal);
        kernel.Process();
    } else {
        KernelForeachAddcdivScalar<bfloat16_t> kernel;
        kernel.Init(x, y, z, out, totalLength, formerNum, formerLength,
                    tailLength, tileLength, scalarVal);
        kernel.Process();
    }
}
