// ForeachAddcdivScalar kernel: out[i] = x[i] + y[i] / z[i] * scalar
// Pure Vector kernel with FP32 upcast for fp16/bf16

#include "kernel_operator.h"

template <typename T>
class KernelForeachAddcdivScalar {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR out,
        int32_t totalLength, int32_t formerNum, int32_t formerLength,
        int32_t tailLength, int32_t tileLength, float scalarVal)
    {
        this->totalLength = totalLength;
        this->formerNum = formerNum;
        this->formerLength = formerLength;
        this->tailLength = tailLength;
        this->tileLength = tileLength;
        this->scalarVal = scalarVal;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), totalLength);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), totalLength);
        zGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(z), totalLength);
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(out), totalLength);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(xBuf_, tileLength * sizeof(T));
            pipe.InitBuffer(yBuf_, tileLength * sizeof(T));
            pipe.InitBuffer(zBuf_, tileLength * sizeof(T));
            pipe.InitBuffer(outBuf_, tileLength * sizeof(T));
            pipe.InitBuffer(tmpFp32Buf_, tileLength * sizeof(float));
            if constexpr (!std::is_same_v<T, float>) {
                pipe.InitBuffer(xFp32Buf_, tileLength * sizeof(float));
                pipe.InitBuffer(yFp32Buf_, tileLength * sizeof(float));
                pipe.InitBuffer(zFp32Buf_, tileLength * sizeof(float));
                pipe.InitBuffer(outFp32Buf_, tileLength * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t tileNum = formerNum + (tailLength > 0 ? 1 : 0);
            for (int32_t i = 0; i < tileNum; ++i) {
                int32_t curLen = (i < formerNum) ? formerLength : tailLength;
                CopyIn(i, curLen);
                Compute(curLen);
                CopyOut(i, curLen);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t tileIdx, int32_t curLen)
    {
        uint32_t offset = static_cast<uint32_t>(tileIdx) * static_cast<uint32_t>(formerLength);
        uint32_t byteLen = static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(T));

        AscendC::DataCopyExtParams copyParams{1, byteLen, 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};

        xLocal_ = xBuf_.Get<T>();
        AscendC::DataCopyPad(xLocal_, xGM_[offset], copyParams, padParams);

        yLocal_ = yBuf_.Get<T>();
        AscendC::DataCopyPad(yLocal_, yGM_[offset], copyParams, padParams);

        zLocal_ = zBuf_.Get<T>();
        AscendC::DataCopyPad(zLocal_, zGM_[offset], copyParams, padParams);

        AscendC::PipeBarrier<PIPE_ALL>();
    }

    __aicore__ inline void Compute(int32_t curLen)
    {
        if constexpr (std::is_same_v<T, float>) {
            xFp32Local_ = xBuf_.Get<float>();
            yFp32Local_ = yBuf_.Get<float>();
            zFp32Local_ = zBuf_.Get<float>();
            outFp32Local_ = outBuf_.Get<float>();
        } else {
            xFp32Local_ = xFp32Buf_.Get<float>();
            yFp32Local_ = yFp32Buf_.Get<float>();
            zFp32Local_ = zFp32Buf_.Get<float>();
            outFp32Local_ = outFp32Buf_.Get<float>();

            AscendC::Cast(xFp32Local_, xLocal_, AscendC::RoundMode::CAST_NONE, curLen);
            AscendC::Cast(yFp32Local_, yLocal_, AscendC::RoundMode::CAST_NONE, curLen);
            AscendC::Cast(zFp32Local_, zLocal_, AscendC::RoundMode::CAST_NONE, curLen);
            AscendC::PipeBarrier<PIPE_V>();
        }

        tmpFp32Local_ = tmpFp32Buf_.Get<float>();

        // Compute: tmp = y / z
        AscendC::Div(tmpFp32Local_, yFp32Local_, zFp32Local_, curLen);

        // Compute: tmp = tmp * scalar
        float s = scalarVal;
        AscendC::Muls(tmpFp32Local_, tmpFp32Local_, s, curLen);

        // Compute: out = x + tmp
        AscendC::Add(outFp32Local_, xFp32Local_, tmpFp32Local_, curLen);

        // Cast back to output dtype
        if constexpr (!std::is_same_v<T, float>) {
            outLocal_ = outBuf_.Get<T>();
            AscendC::Cast(outLocal_, outFp32Local_, AscendC::RoundMode::CAST_ROUND, curLen);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void CopyOut(int32_t tileIdx, int32_t curLen)
    {
        uint32_t offset = static_cast<uint32_t>(tileIdx) * static_cast<uint32_t>(formerLength);
        uint32_t byteLen = static_cast<uint32_t>(curLen) * static_cast<uint32_t>(sizeof(T));
        AscendC::DataCopyExtParams copyParams{1, byteLen, 0, 0, 0};

        if constexpr (std::is_same_v<T, float>) {
            AscendC::DataCopyPad(outGM_[offset], outFp32Local_, copyParams);
        } else {
            AscendC::DataCopyPad(outGM_[offset], outLocal_, copyParams);
        }
    }

private:
    int32_t totalLength = 0;
    int32_t formerNum = 0;
    int32_t formerLength = 0;
    int32_t tailLength = 0;
    int32_t tileLength = 0;
    float scalarVal = 0.0f;

    AscendC::TPipe pipe;

    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;
    AscendC::GlobalTensor<T> zGM_;
    AscendC::GlobalTensor<T> outGM_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> xBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> zBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> zFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outFp32Buf_;

    AscendC::LocalTensor<T> xLocal_;
    AscendC::LocalTensor<T> yLocal_;
    AscendC::LocalTensor<T> zLocal_;
    AscendC::LocalTensor<T> outLocal_;
    AscendC::LocalTensor<float> xFp32Local_;
    AscendC::LocalTensor<float> yFp32Local_;
    AscendC::LocalTensor<float> zFp32Local_;
    AscendC::LocalTensor<float> tmpFp32Local_;
    AscendC::LocalTensor<float> outFp32Local_;
};

