// ForeachAddcdivScalar op_host — tiling + single EXEC_KERNEL_CMD multi-block launch

#include <cstdint>
#include <vector>

#include <torch/extension.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_foreach_addcdiv_scalar.h"

namespace ascend_kernel {

std::vector<at::Tensor> foreach_addcdiv_scalar(
    const std::vector<at::Tensor> &x1,
    const std::vector<at::Tensor> &x2,
    const std::vector<at::Tensor> &x3,
    const at::Tensor &scalar)
{
    int64_t numTensors = static_cast<int64_t>(x1.size());
    TORCH_CHECK(numTensors > 0, "x1 must not be empty");
    TORCH_CHECK(
        static_cast<int64_t>(x2.size()) == numTensors &&
        static_cast<int64_t>(x3.size()) == numTensors,
        "x1, x2, x3 must have the same number of tensors");

    at::ScalarType dtype = x1[0].scalar_type();
    TORCH_CHECK(
        dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
        "dtype must be float32, float16, or bfloat16");

    int64_t dtypeFlag = 0;
    if (dtype == at::kHalf) {
        dtypeFlag = 1;
    } else if (dtype == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // Flatten all tensors into 1D buffers
    std::vector<at::Tensor> xFlatParts, yFlatParts, zFlatParts;
    std::vector<int64_t> sizes;
    int64_t totalLen = 0;
    for (int64_t i = 0; i < numTensors; ++i) {
        TORCH_CHECK(
            x1[i].sizes() == x2[i].sizes() && x1[i].sizes() == x3[i].sizes(),
            "corresponding tensors must have the same shape");
        int64_t n = x1[i].numel();
        xFlatParts.push_back(x1[i].contiguous().view({n}));
        yFlatParts.push_back(x2[i].contiguous().view({n}));
        zFlatParts.push_back(x3[i].contiguous().view({n}));
        sizes.push_back(n);
        totalLen += n;
    }

    at::Tensor xFlat = at::cat(xFlatParts, 0).contiguous();
    at::Tensor yFlat = at::cat(yFlatParts, 0).contiguous();
    at::Tensor zFlat = at::cat(zFlatParts, 0).contiguous();
    at::Tensor outFlat = at::empty({totalLen}, xFlat.options());

    // Scalar
    at::Tensor scalarCpu = scalar.cpu().to(at::kFloat);
    float scalarVal = scalarCpu.item<float>();

    // --- Tiling ---
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // bufferCoeff: fp32=20, fp16/bf16=28
    int32_t elemSize = (dtype == at::kFloat) ? 4 : 2;
    int32_t bufferCoeff = (dtype == at::kFloat) ? 20 : 28;
    int32_t tileLength = static_cast<int32_t>(ubSize) / (bufferCoeff * elemSize);

    // 32B align
    int32_t alignElems = (dtype == at::kFloat) ? 8 : 16;
    tileLength = (tileLength / alignElems) * alignElems;
    if (tileLength < alignElems) {
        tileLength = alignElems;
    }

    int32_t total = static_cast<int32_t>(totalLen);
    int32_t blockNum = static_cast<int32_t>(coreNum);
    if (blockNum > (total + tileLength - 1) / tileLength) {
        blockNum = (total + tileLength - 1) / tileLength;
    }
    if (blockNum < 1) {
        blockNum = 1;
    }

    int32_t elemsPerCore = (total + blockNum - 1) / blockNum;

    // All params as left values
    int32_t totalLengthVal = total;
    int32_t tileLengthVal = tileLength;
    int32_t elemsPerCoreVal = elemsPerCore;
    float scalarVal_ = scalarVal;
    uint32_t blockDim = static_cast<uint32_t>(blockNum);
    int64_t dtypeFlag_ = dtypeFlag;

    EXEC_KERNEL_CMD(
        foreach_addcdiv_scalar, blockDim,
        xFlat, yFlat, zFlat, outFlat,
        totalLengthVal, tileLengthVal, elemsPerCoreVal,
        scalarVal_, dtypeFlag_);

    // Unflatten
    std::vector<at::Tensor> result;
    int64_t offset = 0;
    for (int64_t i = 0; i < numTensors; ++i) {
        int64_t n = sizes[i];
        at::Tensor slice = outFlat.slice(0, offset, offset + n);
        result.push_back(slice.reshape(x1[i].sizes()));
        offset += n;
    }

    return result;
}

}  // namespace ascend_kernel
