// ForeachAddcdivScalar: out[i] = x[i] + (y[i] / z[i]) * scalar
// TIn=half → output half; TIn=bfloat16 → output float (PyTorch promotion)
// Pure Vector, FP32 upcast, multi-block via GetBlockIdx

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

template <typename T>
__aicore__ inline void LoadGmPad(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreUbPad(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

// TIn = input dtype (half, bfloat16_t, float)
// TOut = output dtype (half, float)
// CastBack = true: cast fp32 result → TOut before writing
template <typename TIn, typename TOut, bool CastBack>
class KernelForeachAddcdivScalar {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR out,
        int32_t totalLength, int32_t tileLength, int32_t elemsPerCore,
        float scalarVal)
    {
        this->totalLength = totalLength;
        this->tileLength = tileLength;
        this->elemsPerCore = elemsPerCore;
        this->scalarVal = scalarVal;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ TIn *>(x), totalLength);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ TIn *>(y), totalLength);
        zGM_.SetGlobalBuffer(reinterpret_cast<__gm__ TIn *>(z), totalLength);
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ TOut *>(out), totalLength);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileLength * sizeof(TIn));
            pipe.InitBuffer(yInQueue_, BUFFER_NUM, tileLength * sizeof(TIn));
            pipe.InitBuffer(zInQueue_, BUFFER_NUM, tileLength * sizeof(TIn));
            pipe.InitBuffer(outQueue_, BUFFER_NUM, tileLength * sizeof(TOut));
            pipe.InitBuffer(tmpFp32Buf_, tileLength * sizeof(float));
            if constexpr (!std::is_same_v<TIn, float>) {
                pipe.InitBuffer(xCastBuf_, tileLength * sizeof(float));
                pipe.InitBuffer(yCastBuf_, tileLength * sizeof(float));
                pipe.InitBuffer(zCastBuf_, tileLength * sizeof(float));
            }
            if constexpr (CastBack) {
                pipe.InitBuffer(outCastBuf_, tileLength * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t blockIdx = AscendC::GetBlockIdx();
            int32_t s = blockIdx * elemsPerCore;
            int32_t e = s + elemsPerCore;
            if (e > totalLength) e = totalLength;
            if (s >= totalLength) return;

            for (int32_t cur = s; cur < e; cur += tileLength) {
                int32_t curLen = tileLength;
                if (cur + curLen > e) curLen = e - cur;
                CopyIn(cur, curLen);
                Compute(curLen);
                CopyOut(cur, curLen);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t off, int32_t len)
    {
        uint32_t o = static_cast<uint32_t>(off);
        uint32_t n = static_cast<uint32_t>(len);
        xIn_ = xInQueue_.AllocTensor<TIn>();
        LoadGmPad(xIn_, xGM_[o], n); xInQueue_.EnQue(xIn_);
        yIn_ = yInQueue_.AllocTensor<TIn>();
        LoadGmPad(yIn_, yGM_[o], n); yInQueue_.EnQue(yIn_);
        zIn_ = zInQueue_.AllocTensor<TIn>();
        LoadGmPad(zIn_, zGM_[o], n); zInQueue_.EnQue(zIn_);
    }

    __aicore__ inline void Compute(int32_t len)
    {
        xIn_ = xInQueue_.DeQue<TIn>();
        yIn_ = yInQueue_.DeQue<TIn>();
        zIn_ = zInQueue_.DeQue<TIn>();

        if constexpr (std::is_same_v<TIn, float>) {
            xF32_ = xIn_.template ReinterpretCast<float>();
            yF32_ = yIn_.template ReinterpretCast<float>();
            zF32_ = zIn_.template ReinterpretCast<float>();
        } else {
            xF32_ = xCastBuf_.Get<float>();
            yF32_ = yCastBuf_.Get<float>();
            zF32_ = zCastBuf_.Get<float>();
            AscendC::Cast(xF32_, xIn_, AscendC::RoundMode::CAST_NONE, len);
            AscendC::Cast(yF32_, yIn_, AscendC::RoundMode::CAST_NONE, len);
            AscendC::Cast(zF32_, zIn_, AscendC::RoundMode::CAST_NONE, len);
            AscendC::PipeBarrier<PIPE_V>();
        }

        tmpF32_ = tmpFp32Buf_.Get<float>();

        // y / z
        AscendC::Div(tmpF32_, yF32_, zF32_, len);
        // * scalar
        float s = scalarVal;
        AscendC::Muls(tmpF32_, tmpF32_, s, len);
        // x + tmp
        if constexpr (CastBack) {
            outF32_ = outCastBuf_.Get<float>();
            AscendC::Add(outF32_, xF32_, tmpF32_, len);
            out_ = outQueue_.AllocTensor<TOut>();
            AscendC::Cast(out_, outF32_, AscendC::RoundMode::CAST_ROUND, len);
            AscendC::PipeBarrier<PIPE_V>();
        } else {
            out_ = outQueue_.AllocTensor<TOut>();
            outF32_ = out_.template ReinterpretCast<float>();
            AscendC::Add(outF32_, xF32_, tmpF32_, len);
        }
        outQueue_.EnQue(out_);

        xInQueue_.FreeTensor(xIn_);
        yInQueue_.FreeTensor(yIn_);
        zInQueue_.FreeTensor(zIn_);
    }

    __aicore__ inline void CopyOut(int32_t off, int32_t len)
    {
        uint32_t o = static_cast<uint32_t>(off);
        uint32_t n = static_cast<uint32_t>(len);
        out_ = outQueue_.DeQue<TOut>();
        StoreUbPad(outGM_[o], out_, n);
        outQueue_.FreeTensor(out_);
    }

private:
    int32_t totalLength = 0, tileLength = 0, elemsPerCore = 0;
    float scalarVal = 0.0f;
    AscendC::TPipe pipe;

    AscendC::GlobalTensor<TIn> xGM_, yGM_, zGM_;
    AscendC::GlobalTensor<TOut> outGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_, yInQueue_, zInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_, yCastBuf_, zCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> outCastBuf_, tmpFp32Buf_;

    AscendC::LocalTensor<TIn> xIn_, yIn_, zIn_;
    AscendC::LocalTensor<TOut> out_;
    AscendC::LocalTensor<float> xF32_, yF32_, zF32_, outF32_, tmpF32_;
};

// Entry points
// dtypeFlag: 0=fp32, 1=fp16(f16→f16), 2=bf16(bf16→fp32)

extern "C" __global__ __aicore__ void foreach_addcdiv_scalar(
    GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR out,
    int32_t totalLength, int32_t tileLength, int32_t elemsPerCore,
    float scalarVal, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        // fp32 in, fp32 out, no cast
        KernelForeachAddcdivScalar<float, float, false> k;
        k.Init(x, y, z, out, totalLength, tileLength, elemsPerCore, scalarVal);
        k.Process();
    } else if (dtypeFlag == 1) {
        // fp16 in, fp16 out, cast back
        KernelForeachAddcdivScalar<half, half, true> k;
        k.Init(x, y, z, out, totalLength, tileLength, elemsPerCore, scalarVal);
        k.Process();
    } else {
        // bf16 in, fp32 out, no cast back
        KernelForeachAddcdivScalar<bfloat16_t, float, false> k;
        k.Init(x, y, z, out, totalLength, tileLength, elemsPerCore, scalarVal);
        k.Process();
    }
}
