// ForeachAddcdivScalar op_host

#include <cstdint>
#include <vector>

#include <torch/extension.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_foreach_addcdiv_scalar.h"

namespace ascend_kernel {

std::vector<at::Tensor> foreach_addcdiv_scalar(
    const std::vector<at::Tensor> &x1,
    const std::vector<at::Tensor> &x2,
    const std::vector<at::Tensor> &x3,
    const at::Tensor &scalar)
{
    int64_t nT = static_cast<int64_t>(x1.size());
    TORCH_CHECK(nT > 0, "x1 must not be empty");
    TORCH_CHECK(
        static_cast<int64_t>(x2.size()) == nT && static_cast<int64_t>(x3.size()) == nT,
        "x1, x2, x3 must have same number of tensors");

    at::ScalarType dtype = x1[0].scalar_type();
    TORCH_CHECK(
        dtype == at::kFloat || dtype == at::kHalf || dtype == at::kBFloat16,
        "dtype must be float32, float16, or bfloat16");

    // dtypeFlag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (dtype == at::kHalf) dtypeFlag = 1;
    else if (dtype == at::kBFloat16) dtypeFlag = 2;

    // For bf16: PyTorch promotes bf16+fp32→fp32, so output is fp32
    at::ScalarType outDtype = (dtypeFlag == 2) ? at::kFloat : dtype;

    // Flatten inputs and record sizes
    std::vector<at::Tensor> xP, yP, zP;
    std::vector<int64_t> sizes;
    int64_t totalLen = 0;
    for (int64_t i = 0; i < nT; ++i) {
        TORCH_CHECK(
            x1[i].sizes() == x2[i].sizes() && x1[i].sizes() == x3[i].sizes(),
            "corresponding tensors must have the same shape");
        int64_t n = x1[i].numel();
        xP.push_back(x1[i].contiguous().view({n}));
        yP.push_back(x2[i].contiguous().view({n}));
        zP.push_back(x3[i].contiguous().view({n}));
        sizes.push_back(n);
        totalLen += n;
    }

    at::Tensor xFlat = at::cat(xP, 0).contiguous();
    at::Tensor yFlat = at::cat(yP, 0).contiguous();
    at::Tensor zFlat = at::cat(zP, 0).contiguous();
    at::Tensor outFlat = at::empty({totalLen}, xFlat.options().dtype(outDtype));

    float scalarVal = scalar.cpu().to(at::kFloat).item<float>();

    // --- Tiling ---
    auto pl = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = pl->GetCoreNumAiv();
    uint64_t ubSize;
    pl->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Buffer sizes per dtype:
    // fp32: 3*TQue(TL*4) + 1*TQue(TL*4) + 1*TBuf(TL*4) = 20*TL → coeff=20
    // fp16: 3*TQue(TL*2) + 1*TQue(TL*2) + 4*TBuf(TL*4) + 1*TBuf(TL*4) = 28*TL → coeff=28
    // bf16→fp32: 3*TQue(TL*2) + 1*TQue(TL*4) + 3*TBuf(TL*4) + 1*TBuf(TL*4) = 6+4+12+4=26*TL → coeff=26
    int32_t elemSize, bufferCoeff;
    if (dtypeFlag == 0)      { elemSize = 4; bufferCoeff = 20; }  // fp32
    else if (dtypeFlag == 1) { elemSize = 2; bufferCoeff = 28; }  // fp16
    else                     { elemSize = 2; bufferCoeff = 26; }  // bf16

    int32_t tileLength = static_cast<int32_t>(ubSize) / (bufferCoeff * elemSize);
    int32_t align = (dtypeFlag == 0) ? 8 : 16;  // 32B alignment
    tileLength = (tileLength / align) * align;
    if (tileLength < align) tileLength = align;

    int32_t total = static_cast<int32_t>(totalLen);
    int32_t blockNum = static_cast<int32_t>(coreNum);
    int32_t maxBlocks = (total + tileLength - 1) / tileLength;
    if (blockNum > maxBlocks) blockNum = maxBlocks;
    if (blockNum < 1) blockNum = 1;

    int32_t elemsPerCore = (total + blockNum - 1) / blockNum;

    // Left-value params for EXEC_KERNEL_CMD
    int32_t tl = total, tlen = tileLength, epc = elemsPerCore;
    float s = scalarVal;
    uint32_t bd = static_cast<uint32_t>(blockNum);
    int64_t df = dtypeFlag;

    EXEC_KERNEL_CMD(
        foreach_addcdiv_scalar, bd,
        xFlat, yFlat, zFlat, outFlat,
        tl, tlen, epc, s, df);

    // Unflatten
    std::vector<at::Tensor> result;
    int64_t off = 0;
    for (int64_t i = 0; i < nT; ++i) {
        int64_t n = sizes[i];
        result.push_back(outFlat.slice(0, off, off + n).reshape(x1[i].sizes()));
        off += n;
    }
    return result;
}

}  // namespace ascend_kernel
