#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

template <typename T>
__aicore__ inline void LoadGmPad(
    AscendC::LocalTensor<T> &dst, AscendC::GlobalTensor<T> src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, cp, pp);
}

template <typename T>
__aicore__ inline void StoreUbPad(
    AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams cp{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, cp);
}

//
// Kernel: out = x + ((y / z) * scalar)
//
// TIn / TOut: input/output dtypes.
// ReduceDivToHalf: if true, reduce division precision to TIn by Cast round-trip
//   (needed for bf16: ref does y/z in bf16, we must emulate)
// CastBack: if true, Cast fp32 output back to TOut
//
template <typename TIn, typename TOut, bool ReduceDivToHalf, bool CastBack>
class KernelForeachAddcdivScalar {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR out,
        int32_t totalLength, int32_t tileLength, int32_t elemsPerCore,
        float scalarVal)
    {
        this->totalLength = totalLength;
        this->tileLength = tileLength;
        this->elemsPerCore = elemsPerCore;
        this->scalarVal = scalarVal;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ TIn *>(x), totalLength);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ TIn *>(y), totalLength);
        zGM_.SetGlobalBuffer(reinterpret_cast<__gm__ TIn *>(z), totalLength);
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ TOut *>(out), totalLength);

        if ASCEND_IS_AIV {
            pipe.InitBuffer(xInQ_, BUFFER_NUM, tileLength * sizeof(TIn));
            pipe.InitBuffer(yInQ_, BUFFER_NUM, tileLength * sizeof(TIn));
            pipe.InitBuffer(zInQ_, BUFFER_NUM, tileLength * sizeof(TIn));
            pipe.InitBuffer(outQ_, BUFFER_NUM, tileLength * sizeof(TOut));
            pipe.InitBuffer(tmpFp32_, tileLength * sizeof(float));
            if constexpr (!std::is_same_v<TIn, float>) {
                pipe.InitBuffer(xC_, tileLength * sizeof(float));
                pipe.InitBuffer(yC_, tileLength * sizeof(float));
                pipe.InitBuffer(zC_, tileLength * sizeof(float));
            }
            if constexpr (ReduceDivToHalf) {
                pipe.InitBuffer(halfTmp_, tileLength * sizeof(TIn));
            }
            if constexpr (CastBack) {
                pipe.InitBuffer(outC_, tileLength * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int32_t bi = AscendC::GetBlockIdx();
            int32_t s = bi * elemsPerCore;
            int32_t e = s + elemsPerCore;
            if (e > totalLength) e = totalLength;
            if (s >= totalLength) return;

            for (int32_t cur = s; cur < e; cur += tileLength) {
                int32_t L = tileLength;
                if (cur + L > e) L = e - cur;
                CopyIn(cur, L); Compute(L); CopyOut(cur, L);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t off, int32_t L) {
        uint32_t o = static_cast<uint32_t>(off), n = static_cast<uint32_t>(L);
        xi_ = xInQ_.AllocTensor<TIn>(); LoadGmPad(xi_, xGM_[o], n); xInQ_.EnQue(xi_);
        yi_ = yInQ_.AllocTensor<TIn>(); LoadGmPad(yi_, yGM_[o], n); yInQ_.EnQue(yi_);
        zi_ = zInQ_.AllocTensor<TIn>(); LoadGmPad(zi_, zGM_[o], n); zInQ_.EnQue(zi_);
    }

    __aicore__ inline void Compute(int32_t L) {
        xi_ = xInQ_.DeQue<TIn>();
        yi_ = yInQ_.DeQue<TIn>();
        zi_ = zInQ_.DeQue<TIn>();

        if constexpr (std::is_same_v<TIn, float>) {
            xf_ = xi_.template ReinterpretCast<float>();
            yf_ = yi_.template ReinterpretCast<float>();
            zf_ = zi_.template ReinterpretCast<float>();
        } else {
            xf_ = xC_.Get<float>(); AscendC::Cast(xf_, xi_, AscendC::RoundMode::CAST_NONE, L);
            yf_ = yC_.Get<float>(); AscendC::Cast(yf_, yi_, AscendC::RoundMode::CAST_NONE, L);
            zf_ = zC_.Get<float>(); AscendC::Cast(zf_, zi_, AscendC::RoundMode::CAST_NONE, L);
            AscendC::PipeBarrier<PIPE_V>();
        }

        tf_ = tmpFp32_.Get<float>();

        // y / z
        AscendC::Div(tf_, yf_, zf_, L);

        // Reduce precision to match ref (bf16 does y/z in bf16)
        if constexpr (ReduceDivToHalf) {
            auto ht = halfTmp_.Get<TIn>();
            AscendC::Cast(ht, tf_, AscendC::RoundMode::CAST_ROUND, L);
            AscendC::Cast(tf_, ht, AscendC::RoundMode::CAST_NONE, L);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // * scalar
        float s = scalarVal;
        AscendC::Muls(tf_, tf_, s, L);

        // x + tmp → output
        out_ = outQ_.AllocTensor<TOut>();
        if constexpr (CastBack) {
            auto of = outC_.Get<float>();
            AscendC::Add(of, xf_, tf_, L);
            AscendC::Cast(out_, of, AscendC::RoundMode::CAST_ROUND, L);
            AscendC::PipeBarrier<PIPE_V>();
        } else {
            auto of = out_.template ReinterpretCast<float>();
            AscendC::Add(of, xf_, tf_, L);
        }
        outQ_.EnQue(out_);

        xInQ_.FreeTensor(xi_); yInQ_.FreeTensor(yi_); zInQ_.FreeTensor(zi_);
    }

    __aicore__ inline void CopyOut(int32_t off, int32_t L) {
        uint32_t o = static_cast<uint32_t>(off), n = static_cast<uint32_t>(L);
        out_ = outQ_.DeQue<TOut>(); StoreUbPad(outGM_[o], out_, n); outQ_.FreeTensor(out_);
    }

    int32_t totalLength = 0, tileLength = 0, elemsPerCore = 0;
    float scalarVal = 0.0f;
    AscendC::TPipe pipe;

    AscendC::GlobalTensor<TIn> xGM_, yGM_, zGM_;
    AscendC::GlobalTensor<TOut> outGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQ_, yInQ_, zInQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQ_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> xC_, yC_, zC_, tmpFp32_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> halfTmp_, outC_;

    AscendC::LocalTensor<TIn> xi_, yi_, zi_;
    AscendC::LocalTensor<TOut> out_;
    AscendC::LocalTensor<float> xf_, yf_, zf_, tf_;
};

// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
extern "C" __global__ __aicore__ void foreach_addcdiv_scalar(
    GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR out,
    int32_t totalLength, int32_t tileLength, int32_t elemsPerCore,
    float scalarVal, int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        KernelForeachAddcdivScalar<float, float, false, false> k;
        k.Init(x, y, z, out, totalLength, tileLength, elemsPerCore, scalarVal);
        k.Process();
    } else if (dtypeFlag == 1) {
        KernelForeachAddcdivScalar<half, half, false, true> k;
        k.Init(x, y, z, out, totalLength, tileLength, elemsPerCore, scalarVal);
        k.Process();
    } else {
        // bf16 in, fp32 out, reduce div to bf16 precision, no cast back
        KernelForeachAddcdivScalar<bfloat16_t, float, true, false> k;
        k.Init(x, y, z, out, totalLength, tileLength, elemsPerCore, scalarVal);
        k.Process();
    }
}
